package com.nephh.business;
import com.nephh.common.ApiResponse;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import static com.nephh.business.AccessService.*;

@RestController @RequestMapping("/api/business")
public class ReportController {
 private final NamedParameterJdbcTemplate db;private final AccessService access;
 public ReportController(JdbcTemplate jdbc,AccessService access){this.db=new NamedParameterJdbcTemplate(jdbc);this.access=access;}
 private record Scope(String filter,Map<String,Object> args){}
 private Scope scope(Jwt jwt,Long areaId,Instant from,Instant to){var a=access.actor(jwt);access.manager(a);Instant end=to==null?Instant.now():to,start=from==null?end.minusSeconds(30*86400L):from;if(!start.isBefore(end)||start.plusSeconds(366*86400L).isBefore(end))bad("报表时间范围为1秒至366天");var args=new HashMap<String,Object>();args.put("user",a.id());args.put("from",Timestamp.from(start));args.put("to",Timestamp.from(end));String filter=a.role().equals("ADMIN")?"":" and n.area_id in(select area_id from user_area where user_id=:user)";if(areaId!=null){access.area(a,areaId);args.put("area",areaId);filter+=" and n.area_id=:area";}return new Scope(filter,args);}
 @GetMapping("/statistics") public ApiResponse<?> statistics(@AuthenticationPrincipal Jwt jwt,@RequestParam(required=false)Long areaId,@RequestParam(required=false)Instant from,@RequestParam(required=false)Instant to){var s=scope(jwt,areaId,from,to);String orders=" from work_order o join monitoring_node n on n.id=o.node_id where o.created_at between :from and :to"+s.filter;String alarms=" from alarm al join monitoring_node n on n.id=al.node_id where al.triggered_at between :from and :to"+s.filter;var result=new LinkedHashMap<String,Object>();result.put("orders",db.queryForList("select o.status,count(*) total"+orders+" group by o.status",s.args));result.put("alarms",db.queryForList("select al.severity,count(*) total"+alarms+" group by al.severity",s.args));result.put("overdue",db.queryForObject("select count(*)"+orders+" and o.due_at<CURRENT_TIMESTAMP and o.status not in('COMPLETED','CANCELLED')",s.args,Integer.class));result.put("repeatNodes",db.queryForList("select n.code,count(*) total"+alarms+" group by n.code having count(*)>1 order by total desc",s.args));result.put("averageResponseSeconds",db.queryForObject("select avg(TIMESTAMPDIFF(SECOND,o.created_at,e.created_at)) from work_order o join monitoring_node n on n.id=o.node_id join order_event e on e.order_id=o.id and e.action='ACCEPT' where o.created_at between :from and :to"+s.filter,s.args,Double.class));result.put("coverage",db.queryForMap("select count(*) total,coalesce(sum(case when pr.checked_at is not null then 1 else 0 end),0) checked from patrol_result pr join patrol_run r on r.id=pr.run_id join monitoring_node n on n.id=pr.node_id where r.created_at between :from and :to"+s.filter,s.args));result.put("from",s.args.get("from"));result.put("to",s.args.get("to"));
 result.put("alarmRecovery",db.queryForMap("select count(*) total,coalesce(sum(case when al.recovered_at is not null then 1 else 0 end),0) recovered"+alarms,s.args));
 var monthArgs=new HashMap<String,Object>(s.args);monthArgs.put("monthStart",Timestamp.from(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")).withDayOfMonth(1).atStartOfDay(java.time.ZoneId.of("Asia/Shanghai")).toInstant()));result.put("monthlyAlarms",db.queryForObject("select count(*) from alarm al join monitoring_node n on n.id=al.node_id where al.triggered_at>=:monthStart"+s.filter,monthArgs,Integer.class));
 int available=db.queryForObject("select count(*) from monitoring_node n where n.enabled=true"+s.filter,s.args,Integer.class);
 var weekStart=((Timestamp)s.args.get("to")).toInstant().atZone(java.time.ZoneId.of("Asia/Shanghai")).toLocalDate().with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY));var weekly=new ArrayList<Map<String,Object>>();
 for(int i=0;i<12;i++){var args=new HashMap<String,Object>(s.args);var startWeek=weekStart.minusWeeks(11-i);args.put("weekStart",Timestamp.from(startWeek.atStartOfDay(java.time.ZoneId.of("Asia/Shanghai")).toInstant()));args.put("weekEnd",Timestamp.from(startWeek.plusWeeks(1).atStartOfDay(java.time.ZoneId.of("Asia/Shanghai")).toInstant()));var counts=db.queryForMap("select count(distinct pr.node_id) planned,count(distinct case when pr.checked_at is not null then pr.node_id else null end) completed from patrol_result pr join patrol_run r on r.id=pr.run_id join monitoring_node n on n.id=pr.node_id where r.created_at>=:weekStart and r.created_at<:weekEnd"+s.filter,args);weekly.add(Map.of("label","W"+(i+1),"planned",available==0?0:Math.min(100,((Number)counts.get("planned")).doubleValue()/available*100),"completed",available==0?0:Math.min(100,((Number)counts.get("completed")).doubleValue()/available*100)));}result.put("weekly",weekly);return ApiResponse.ok(result);}
 @GetMapping("/reports") public ApiResponse<?> report(@AuthenticationPrincipal Jwt jwt,@RequestParam String type,@RequestParam(required=false)Long areaId,@RequestParam(required=false)Instant from,@RequestParam(required=false)Instant to){var s=scope(jwt,areaId,from,to);String sql;if(type.equals("orders"))sql="select o.id,o.title,n.code node,o.priority,o.status,u.username assignee,o.created_at,o.due_at,o.result_text from work_order o join monitoring_node n on n.id=o.node_id left join sys_user u on u.id=o.assignee_id where o.created_at between :from and :to"+s.filter+" order by o.id desc limit 10001";else if(type.equals("alarms"))sql="select al.id,n.code node,al.metric,al.severity,al.reason,al.status,al.triggered_at,al.recovered_at from alarm al join monitoring_node n on n.id=al.node_id where al.triggered_at between :from and :to"+s.filter+" order by al.id desc limit 10001";else{bad("报表类型不存在");return ApiResponse.ok(null);}var rows=db.queryForList(sql,s.args);if(rows.size()>10000)bad("导出超过10000条，请缩小时间范围");return ApiResponse.ok(rows);}
}
